#!/usr/bin/env python3
"""
Test script for SummaryEngine functionality
"""

import asyncio
import os
import sys
sys.path.append(os.path.dirname(os.path.abspath(__file__)))

from summary_engine import (
    SummaryEngine, 
    SummaryMode, 
    ContentType, 
    create_summary_engine
)


async def test_summary_engine():
    """Test SummaryEngine functionality"""
    print("🧪 Testing SummaryEngine...")
    
    # Create summary engine
    summary_engine = create_summary_engine()
    
    # Test 1: Mode determination
    print("\n📋 Test 1: Mode determination")
    
    # Test content type routing
    test_cases = [
        (ContentType.TELEGRAM_VOICE, "Короткое голосовое сообщение", 30),
        (ContentType.TELEGRAM_VIDEO_NOTE, "Видео заметка", 45),
        (ContentType.TELEGRAM_DOCUMENT, "Длинный документ с много текста", None),
        (ContentType.TELEGRAM_VIDEO, "Видео файл", 720),  # 12 minutes
        (ContentType.UPLOADED_URL, "Внешняя ссылка на контент", None),
    ]
    
    for content_type, description, duration in test_cases:
        mode = summary_engine.determine_mode(content_type, description, duration)
        print(f"  {content_type.value}: {description} ({duration}s) → {mode.value}")
    
    # Test 2: Long text heuristic
    print("\n📋 Test 2: Long text heuristic")
    long_text = "Это очень длинный текст " * 100  # ~2000 words
    mode = summary_engine.determine_mode(ContentType.TEXT_INPUT, long_text)
    print(f"  Long text ({len(long_text.split())} words) → {mode.value}")
    
    # Test 3: Dialog style heuristic
    print("\n📋 Test 3: Dialog style heuristic")
    dialog_text = "Я думаю, что ты прав. Мы должны это сделать. Он сказал, что она согласна. Вы понимаете?"
    mode = summary_engine.determine_mode(ContentType.UPLOADED_URL, dialog_text)
    print(f"  Dialog text → {mode.value}")
    
    # Test 4: Configuration
    print("\n📋 Test 4: Configuration")
    chat_config = summary_engine.configs[SummaryMode.CHAT]
    longform_config = summary_engine.configs[SummaryMode.LONGFORM]
    
    print(f"  CHAT mode: {chat_config.model}, {chat_config.max_tokens} tokens")
    print(f"  LONGFORM mode: {longform_config.model}, {longform_config.max_tokens} tokens")
    
    # Test 5: Fallback responses
    print("\n📋 Test 5: Fallback responses")
    
    fallback_cases = [
        ("", "Empty text"),
        ("шум и музыка", "Noise text"),
        ("Обычный текст для анализа", "Normal text"),
    ]
    
    for text, description in fallback_cases:
        fallback = summary_engine.get_fallback_response(text)
        print(f"  {description}: {fallback[:50]}...")
    
    print("\n✅ SummaryEngine tests completed!")


async def test_summary_processing():
    """Test actual summary processing (requires OpenAI API)"""
    print("\n🧪 Testing summary processing...")
    
    # Check if OpenAI API key is available
    if not os.getenv('OPENAI_API_KEY'):
        print("⚠️  OPENAI_API_KEY not set, skipping processing tests")
        return
    
    # Enable summary engine
    summary_engine = create_summary_engine()
    summary_engine.enable()
    
    # Test cases
    test_cases = [
        {
            "text": "Привет! Я хочу рассказать о своем проекте. Мы разрабатываем новое приложение для анализа данных. Проект начался в январе 2024 года, и сейчас у нас уже есть прототип. Команда состоит из 5 разработчиков и 2 дизайнеров. Бюджет проекта составляет 500,000 рублей. Мы планируем запустить первую версию в марте 2024 года.",
            "content_type": ContentType.TELEGRAM_VOICE,
            "description": "Short project description"
        },
        {
            "text": "Это очень длинный текст о технологии блокчейн. Блокчейн - это распределенная база данных, которая содержит постоянно растущий список записей, защищенных от подделки и пересмотра. Каждый блок содержит временную метку и ссылку на предыдущий блок. Блокчейн может использоваться для создания неизменяемых записей о любых данных. Технология была впервые применена в 2008 году Сатоши Накамото для создания криптовалюты Bitcoin. С тех пор блокчейн нашел применение в различных областях: от финансовых услуг до управления цепочками поставок. Основные преимущества блокчейна включают децентрализацию, прозрачность, неизменность и безопасность. Однако технология также сталкивается с проблемами масштабируемости и энергопотребления. В 2023 году рынок блокчейн-технологий оценивался в 19.9 миллиардов долларов США. Ожидается, что к 2030 году этот рынок достигнет 469.49 миллиардов долларов. Крупные компании, такие как IBM, Microsoft и Amazon, активно инвестируют в блокчейн-решения. Правительства различных стран также изучают возможности использования блокчейна для цифровизации государственных услуг. В России блокчейн-технологии развиваются в рамках национальной программы 'Цифровая экономика'. Центральный банк России тестирует цифровой рубль на блокчейн-платформе. В 2024 году планируется запуск пилотного проекта по использованию цифрового рубля в розничных платежах. Эксперты прогнозируют, что блокчейн станет основой для Web 3.0 - следующего поколения интернета. Технология смарт-контрактов позволяет автоматизировать выполнение соглашений без участия посредников. Это открывает новые возможности для создания децентрализованных приложений (dApps). Платформы Ethereum, Solana и Polkadot являются лидерами в области смарт-контрактов. Однако высокая волатильность криптовалют и регуляторная неопределенность создают риски для инвесторов. В 2023 году произошло несколько крупных крахов криптобирж, включая FTX и Celsius. Это привело к ужесточению регулирования криптовалютного рынка во многих странах. Европейский союз принял регламент MiCA (Markets in Crypto-Assets), который вступит в силу в 2024 году. В США Комиссия по ценным бумагам и биржам (SEC) активно преследует криптопроекты за нарушение законов о ценных бумагах. Несмотря на эти вызовы, интерес к блокчейн-технологиям продолжает расти. Венчурные фонды инвестировали более 30 миллиардов долларов в блокчейн-стартапы в 2023 году. Университеты по всему миру предлагают курсы по блокчейн-технологиям. Крупные технологические компании создают собственные блокчейн-платформы. Например, Facebook (Meta) разрабатывает блокчейн-платформу Diem для цифровых платежей. В будущем блокчейн может стать основой для создания метавселенных - виртуальных миров, где пользователи могут взаимодействовать друг с другом и с цифровыми активами. Технология NFT (невзаимозаменяемые токены) уже используется для создания уникальных цифровых активов. В 2023 году объем торговли NFT составил более 24 миллиардов долларов. Однако рынок NFT переживает спад из-за снижения интереса к цифровому искусству. Эксперты считают, что реальная ценность блокчейна заключается не в спекулятивных активах, а в решении реальных бизнес-проблем. Технология может революционизировать такие отрасли, как здравоохранение, образование, логистика и энергетика. Например, блокчейн может обеспечить безопасный обмен медицинскими данными между больницами. В образовании блокчейн может использоваться для верификации дипломов и сертификатов. В логистике технология может обеспечить прозрачность цепочки поставок и предотвратить подделку товаров. В энергетике блокчейн может использоваться для создания децентрализованных энергетических сетей. Потребители смогут продавать избыточную энергию от солнечных панелей другим пользователям. Это создаст новую экономическую модель в энергетическом секторе. Однако для широкого внедрения блокчейн-технологий необходимо решить технические и регуляторные проблемы. Масштабируемость остается основной проблемой блокчейн-сетей. Bitcoin может обрабатывать только 7 транзакций в секунду, что недостаточно для массового использования. Ethereum 2.0 должен решить эту проблему с помощью технологии Proof of Stake. Однако переход на новую версию Ethereum занял несколько лет и сопровождался техническими сложностями. Альтернативные решения, такие как Lightning Network для Bitcoin и Layer 2 решения для Ethereum, также направлены на повышение пропускной способности. Однако эти решения добавляют сложность и могут создавать новые проблемы безопасности. Энергопотребление блокчейн-сетей также является серьезной проблемой. Bitcoin потребляет больше электроэнергии, чем некоторые страны. Это вызывает обеспокоенность по поводу воздействия на окружающую среду. Переход на Proof of Stake должен значительно снизить энергопотребление. Ethereum уже сократил энергопотребление на 99% после перехода на Proof of Stake. Однако некоторые эксперты считают, что Proof of Stake менее безопасен, чем Proof of Work. В будущем могут появиться новые консенсусные алгоритмы, которые объединят преимущества обеих технологий. Регуляторная неопределенность также замедляет внедрение блокчейн-технологий. Правительства различных стран по-разному относятся к криптовалютам и блокчейну. Некоторые страны, такие как Сальвадор, приняли Bitcoin в качестве законного платежного средства. Другие страны, такие как Китай, запретили криптовалюты. В России криптовалюты не являются законным платежным средством, но их владение не запрещено. Центральный банк России планирует создать цифровой рубль, который будет использовать блокчейн-технологии. Это может стать альтернативой криптовалютам и обеспечить контроль государства над цифровыми платежами. В будущем блокчейн может стать основой для создания новой финансовой системы. Децентрализованные финансы (DeFi) уже предлагают альтернативы традиционным финансовым услугам. Пользователи могут брать кредиты, торговать активами и получать проценты без участия банков. Однако DeFi также сталкивается с проблемами безопасности и регулирования. В 2023 году произошло несколько крупных взломов DeFi-протоколов, в результате которых были украдены миллионы долларов. Это показывает, что безопасность остается критически важной проблемой для блокчейн-технологий. В заключение, блокчейн-технологии имеют огромный потенциал для трансформации различных отраслей экономики. Однако для реализации этого потенциала необходимо решить технические, регуляторные и социальные проблемы. Будущее блокчейна зависит от способности сообщества преодолеть эти вызовы и создать устойчивую экосистему. Технология может стать основой для более справедливого и прозрачного общества, но путь к этому будущему будет непростым.",
            "content_type": ContentType.TELEGRAM_DOCUMENT,
            "description": "Long blockchain article"
        }
    ]
    
    for i, test_case in enumerate(test_cases, 1):
        print(f"\n  📝 Test {i}: {test_case['description']}")
        
        try:
            result = await summary_engine.process_summary(
                text=test_case['text'],
                content_type=test_case['content_type']
            )
            
            if result.success:
                print(f"    ✅ Success: {result.mode.value} mode")
                print(f"    ⏱️  Time: {result.processing_time:.2f}s")
                print(f"    🎯 Tokens: {result.token_count}")
                print(f"    📊 Confidence: {result.confidence}")
                print(f"    📄 Summary preview: {result.summary[:100]}...")
            else:
                print(f"    ❌ Failed: {result.error_message}")
                
        except Exception as e:
            print(f"    ❌ Exception: {e}")
    
    print("\n✅ Summary processing tests completed!")


async def main():
    """Main test function"""
    print("🚀 Starting SummaryEngine tests...\n")
    
    # Test basic functionality
    await test_summary_engine()
    
    # Test actual processing
    await test_summary_processing()
    
    print("\n🎉 All tests completed!")


if __name__ == "__main__":
    asyncio.run(main()) 